// === Tab: mySketch ===
// Translated to p5.js fork: oggy  https://openprocessing.org/sketch/555063

const numb = 55;
const step = 8;
const dist = 50;
const distortion = 15;
let dots = [];

function setup() {
  createCanvas(600, 600);
	background(200);
	stroke(256);
  const dx = (width - numb * step) / 2;
  for (let i = 0; i < numb; i++) {
    dots[i] = [];
    for (let j = 0; j < numb; j++) {
      dots[i][j] = new Dot(i * step + dx, j * step + dx);
    }
  }
}

function draw() {
	fill(0);
  rect(0, 0, width, height);
  const m = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  for (let i = 0; i < numb; i++) {
    for (let j = 0; j < numb; j++) {
      dots[i][j].update(m);
    }
  }
}

class Dot {
  constructor(x, y) {
    this.pos = createVector(x, y);
    this.origin = this.pos.copy();
    this.speed = createVector(0, 0);
  }

  update(m) {
    let tmp = this.origin.copy();
    tmp.sub(m);
    const d = tmp.mag();
    const c = map(d, 0, dist, 0, PI);
    tmp.normalize();
    tmp.mult(distortion * sin(c));

    let strokeWidth;
    if (d < dist) strokeWidth = 1 + 10 * abs(cos(c / 2));
    else strokeWidth = map(min(d, width), 0, width, 5, 0.1);

    const target = createVector(this.origin.x + tmp.x, this.origin.y + tmp.y);
    tmp = this.pos.copy();
    tmp.sub(target);
    tmp.mult(-map(m.dist(this.pos), 0, 2 * width, 0.1, 0.01));
    this.speed.add(tmp);
    this.speed.mult(0.87);
    this.pos.add(this.speed);

    strokeWeight(strokeWidth);
    point(this.pos.x, this.pos.y);
  }
}

